function snapshot_ToyPhys()
% Self-contained snapshot generated by simulink-snapshot-edit.
% Run once to rebuild ToyPhys.slx exactly (blocks/params/positions/routing).
% Local-edit workflow: edit only the lines of the block you need.
  if bdIsLoaded('ToyPhys'), close_system('ToyPhys', 0); end
  new_system('ToyPhys');
  m = 'ToyPhys';

  % ---- solver / config / model params ----

  % ---- callbacks ----

  % ---- Model Workspace variables ----

  % ---- blocks (positions & full parameters preserved) ----
  add_block('fl_lib/Electrical/Electrical Elements/Capacitor', [m '/c1'], 'Position', [180 60 220 100], 'c', '1e-6', 'c_unit', 'F', 'c_conf', 'compiletime', 'r', '1e-6', 'r_unit', 'Ohm', 'r_conf', 'compiletime', 'g', '0', 'g_unit', '1/Ohm', 'g_conf', 'compiletime', 'i_specify', 'off', 'i_priority', 'None', 'i', '0', 'i_unit', 'A', 'i_nominal_specify', 'off', 'i_nominal_unit', 'A', 'i_nominal_value', '1', 'v_specify', 'off', 'v_priority', 'None', 'v', '0', 'v_unit', 'V', 'v_nominal_specify', 'off', 'v_nominal_unit', 'V', 'v_nominal_value', '1', 'vc_specify', 'off', 'vc_priority', 'High', 'vc', '0', 'vc_unit', 'V', 'vc_nominal_specify', 'off', 'vc_nominal_unit', 'V', 'vc_nominal_value', '1');
  add_block('fl_lib/Electrical/Electrical Elements/Electrical Reference', [m '/gnd'], 'Position', [300 180 340 220]);
  add_block('fl_lib/Electrical/Electrical Elements/Inductor', [m '/l1'], 'Position', [300 60 340 100], 'l', '1e-6', 'l_unit', 'H', 'l_conf', 'compiletime', 'r', '0', 'r_unit', 'Ohm', 'r_conf', 'compiletime', 'g', '1e-9', 'g_unit', '1/Ohm', 'g_conf', 'compiletime', 'i_specify', 'off', 'i_priority', 'None', 'i', '0', 'i_unit', 'A', 'i_nominal_specify', 'off', 'i_nominal_unit', 'A', 'i_nominal_value', '1', 'v_specify', 'off', 'v_priority', 'None', 'v', '0', 'v_unit', 'V', 'v_nominal_specify', 'off', 'v_nominal_unit', 'V', 'v_nominal_value', '1', 'i_L_specify', 'off', 'i_L_priority', 'High', 'i_L', '0', 'i_L_unit', 'A', 'i_L_nominal_specify', 'off', 'i_L_nominal_unit', 'A', 'i_L_nominal_value', '1');
  add_block('fl_lib/Electrical/Electrical Elements/Resistor', [m '/r1'], 'Position', [60 60 100 100], 'R', '1', 'R_unit', 'Ohm', 'R_conf', 'compiletime', 'i_specify', 'off', 'i_priority', 'None', 'i', '0', 'i_unit', 'A', 'i_nominal_specify', 'off', 'i_nominal_unit', 'A', 'i_nominal_value', '1', 'v_specify', 'off', 'v_priority', 'None', 'v', '0', 'v_unit', 'V', 'v_nominal_specify', 'off', 'v_nominal_unit', 'V', 'v_nominal_value', '1');
  try, set_param(m, 'SimulationCommand', 'update'); catch, end

  % ---- lines ----

  % ---- physical (Simscape) connections ----
  add_line(m, 'c1/LConn1', 'r1/LConn1');
  add_line(m, 'c1/RConn1', 'l1/LConn1');
  add_line(m, 'gnd/LConn1', 'l1/RConn1');

  % ---- annotations (top level) ----

  snpDir = fileparts(mfilename('fullpath'));
  snpOut = fullfile(snpDir, '..\models');
  try, bdclose('ToyPhys_tmp_save'); catch, end
  if ~isfolder(snpOut), mkdir(snpOut); end
  if isfile(fullfile(snpOut, 'ToyPhys_tmp_save.slx')), delete(fullfile(snpOut, 'ToyPhys_tmp_save.slx')); end
  save_system(m, fullfile(snpOut, 'ToyPhys_tmp_save.slx'));
  close_system(m, 0);
  movefile(fullfile(snpOut, 'ToyPhys_tmp_save.slx'), fullfile(snpOut, 'ToyPhys.slx'), 'f');
end

